def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for top in range(h):
        # Columns that remain equal to a particular color through this span.
        for color in set(grid[top]):
            valid = [grid[top][c] == color for c in range(w)]
            for bottom in range(top, h):
                if bottom > top:
                    valid = [valid[c] and grid[bottom][c] == color for c in range(w)]
                height = bottom - top + 1
                if height < 4:
                    continue
                c = 0
                while c < w:
                    if valid[c]:
                        start = c
                        while c < w and valid[c]: c += 1
                        if c - start >= 4:
                            for r in range(top, bottom + 1):
                                for cc in range(start, c): out[r][cc] = 4
                    else:
                        c += 1
    return out
